from .preprocessing import get_sot_gene_matrix
def safe_sum(X):
    # Handles both sparse and dense matrices robustly
    if issparse(X):
        # .A1 is only available for 1D sparse matrices; use .toarray().ravel() for generality
        return np.asarray(X.sum(axis=0)).ravel()
    else:
        return np.asarray(X.sum(axis=0)).ravel()

def build_isoform_metrics_table(
    adata: "anndata.AnnData",
    group_column: str,
    condition_column: str = None,
    comparisons: list = None,
    group_vs_rest: bool = False,
    epsilon: float = 1e-6,
    n_jobs: int = -1
) -> pd.DataFrame:
    """
    Compare levels in `group_column` at isoform level.
    If group_vs_rest=True, compares each group vs. all other cells.
    Otherwise does pairwise (or custom `comparisons`).
    """
    ad = adata.copy()
    tx_ids = ad.var.index.values
    gene_ids = ad.var['geneId'].values
    gene2tx = defaultdict(list)
    for idx, g in enumerate(gene_ids):
        gene2tx[g].append(idx)
    gene2tx = {g: np.array(v, dtype=int) for g, v in gene2tx.items()}

    def safe_sum_inner(X):
        if issparse(X):
            return np.asarray(X.sum(axis=0)).ravel()
        else:
            return np.asarray(X.sum(axis=0)).ravel()

    tasks = []
    if condition_column is not None:
        primaries = sorted(ad.obs[group_column].unique())
        conds = sorted(ad.obs[condition_column].unique())
        for pg in primaries:
            base = ad.obs[group_column] == pg
            for c1, c2 in itertools.combinations(conds, 2):
                m1 = base & (ad.obs[condition_column] == c1)
                m2 = base & (ad.obs[condition_column] == c2)
                tasks.append((m1.values, m2.values, f"{pg}:{c1}", f"{pg}:{c2}"))
    else:
        groups = sorted(ad.obs[group_column].unique())
        if group_vs_rest:
            for g in groups:
                m1 = ad.obs[group_column] == g
                m2 = ~m1
                tasks.append((m1.values, m2.values, str(g), 'rest'))
        else:
            pairs = comparisons or itertools.combinations(groups, 2)
            for g1, g2 in pairs:
                m1 = ad.obs[group_column] == g1
                m2 = ad.obs[group_column] == g2
                tasks.append((m1.values, m2.values, str(g1), str(g2)))

    def process_one(m1, m2, lab1, lab2):
        A1, A2 = ad[m1], ad[m2]
        X1, X2 = A1.X, A2.X
        n1, n2 = A1.n_obs, A2.n_obs
        c1, c2 = safe_sum_inner(X1), safe_sum_inner(X2)
        mexpr1, mexpr2 = c1/n1, c2/n2
        if issparse(X1):
            # .A1 is only for 1D, so use .toarray() and ravel for generality
            p1 = (X1 > 0).mean(axis=0).A1*100 if hasattr((X1 > 0).mean(axis=0), "A1") else np.asarray((X1 > 0).mean(axis=0)).ravel()*100
            p2 = (X2 > 0).mean(axis=0).A1*100 if hasattr((X2 > 0).mean(axis=0), "A1") else np.asarray((X2 > 0).mean(axis=0)).ravel()*100
        else:
            p1 = (X1 > 0).sum(axis=0).ravel()/n1*100
            p2 = (X2 > 0).sum(axis=0).ravel()/n2*100

        out = defaultdict(list)
        for gene, idxs in gene2tx.items():
            M1 = X1[:, idxs]; M2 = X2[:, idxs]
            rs1 = np.asarray(M1.sum(axis=1)).ravel() + epsilon
            rs2 = np.asarray(M2.sum(axis=1)).ravel() + epsilon
            # diags expects 1D arrays
            D1 = diags(1.0/rs1)
            D2 = diags(1.0/rs2)
            # D1.dot(M1) is (cells x tx), sum(axis=0) is tx
            # For sparse, .A1 is only for 1D, so use .toarray().ravel()
            ps1_raw = D1.dot(M1).sum(axis=0)
            ps2_raw = D2.dot(M2).sum(axis=0)
            if issparse(ps1_raw):
                ps1 = np.asarray(ps1_raw).ravel()/n1
            else:
                ps1 = np.asarray(ps1_raw).ravel()/n1
            if issparse(ps2_raw):
                ps2 = np.asarray(ps2_raw).ravel()/n2
            else:
                ps2 = np.asarray(ps2_raw).ravel()/n2
            lfc = np.log((ps1+epsilon)/(ps2+epsilon))
            dpsi = ps1-ps2
            L = len(idxs)
            out['comparison'].extend([f"{lab1}__{lab2}"]*L)
            out['gene_id'].extend([gene]*L)
            out['transcript_id'].extend(tx_ids[idxs])
            out['group_1'].extend([lab1]*L)
            out['group_2'].extend([lab2]*L)
            out['count_group1'].extend(c1[idxs].tolist())
            out['count_group2'].extend(c2[idxs].tolist())
            out['mean_expr_group1'].extend(mexpr1[idxs].tolist())
            out['mean_expr_group2'].extend(mexpr2[idxs].tolist())
            out['percent_expr_group1'].extend(p1[idxs].tolist())
            out['percent_expr_group2'].extend(p2[idxs].tolist())
            out['avg_psi_group1'].extend(ps1.tolist())
            out['log_fc'].extend(lfc.tolist())
            out['delta_psi'].extend(dpsi.tolist())
            out['n_cells_group1'].extend([n1]*L)
            out['n_cells_group2'].extend([n2]*L)
            out['total_cells'].extend([n1+n2]*L)
            out['total_count'].extend((c1[idxs]+c2[idxs]).tolist())
        return pd.DataFrame(out)

    dfs = Parallel(n_jobs=n_jobs)(
        delayed(process_one)(m1, m2, l1, l2) for m1, m2, l1, l2 in tasks
    )
    return pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()


def build_gene_metrics_table(
    adata: "anndata.AnnData",
    group_column: str,
    condition_column: str = None,
    comparisons: list = None,
    group_vs_rest: bool = False,
    epsilon: float = 1e-6,
    n_jobs: int = -1
) -> pd.DataFrame:
    """
    Compare levels in `group_column` at gene level.
    If group_vs_rest=True, compares each group vs. all other cells.
    """
    adf = get_sot_gene_matrix(adata)
    if 'geneId' not in adf.var.columns:
        adf.var['geneId'] = adf.var.index

    def safe_sum_inner(X):
        if issparse(X):
            return np.asarray(X.sum(axis=0)).ravel()
        else:
            return np.asarray(X.sum(axis=0)).ravel()

    tasks = []
    groups = sorted(adf.obs[group_column].unique())
    if group_vs_rest:
        for g in groups:
            m1 = adf.obs[group_column] == g
            m2 = ~m1
            tasks.append((m1.values, m2.values, str(g), 'rest'))
    else:
        if condition_column is not None:
            prim, conds = sorted(adf.obs[group_column].unique()), sorted(adf.obs[condition_column].unique())
            for pg in prim:
                for c1, c2 in itertools.combinations(conds, 2):
                    m1 = (adf.obs[group_column] == pg) & (adf.obs[condition_column] == c1)
                    m2 = (adf.obs[group_column] == pg) & (adf.obs[condition_column] == c2)
                    tasks.append((m1.values, m2.values, f"{pg}:{c1}", f"{pg}:{c2}"))
        else:
            pairs = comparisons or itertools.combinations(groups, 2)
            for g1, g2 in pairs:
                m1 = adf.obs[group_column] == g1
                m2 = adf.obs[group_column] == g2
                tasks.append((m1.values, m2.values, str(g1), str(g2)))

    def proc(m1, m2, l1, l2):
        A1, A2 = adf[m1], adf[m2]
        X1, X2 = A1.X, A2.X
        n1, n2 = A1.n_obs, A2.n_obs
        c1, c2 = safe_sum_inner(X1), safe_sum_inner(X2)
        me1, me2 = c1/n1, c2/n2
        if issparse(X1):
            p1_raw = (X1 > 0).mean(axis=0)
            p2_raw = (X2 > 0).mean(axis=0)
            p1 = p1_raw.A1*100 if hasattr(p1_raw, "A1") else np.asarray(p1_raw).ravel()*100
            p2 = p2_raw.A1*100 if hasattr(p2_raw, "A1") else np.asarray(p2_raw).ravel()*100
        else:
            p1 = (X1 > 0).sum(axis=0).ravel()/n1*100
            p2 = (X2 > 0).sum(axis=0).ravel()/n2*100
        lfc = np.log((me1+epsilon)/(me2+epsilon))
        genes = adf.var.index.values
        tot = c1 + c2
        comp = f"{l1}__{l2}"
        return pd.DataFrame({
            'comparison': [comp]*len(genes),
            'gene_id': genes,
            'group_1': [l1]*len(genes),
            'group_2': [l2]*len(genes),
            'count_group1': c1,
            'count_group2': c2,
            'mean_expr_group1': me1,
            'mean_expr_group2': me2,
            'percent_expr_group1': p1,
            'percent_expr_group2': p2,
            'log_fc': lfc,
            'n_cells_group1': [n1]*len(genes),
            'n_cells_group2': [n2]*len(genes),
            'total_cells': [n1+n2]*len(genes),
            'total_count': tot
        })

    dfs = Parallel(n_jobs=n_jobs)(delayed(proc)(*t) for t in tasks)
    return pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()

