import warnings
import itertools
import os
from typing import Dict, List, Optional

import anndata as ad
import numpy as np
import pandas as pd
from joblib import Parallel, delayed
from numba import njit
from scipy.stats import chi2  # p‑value outside Numba
from scipy.sparse import issparse

# ---------------------------------------------------------------------------
# Utility helpers
# ---------------------------------------------------------------------------

def safe_sum(x):
    """Axis‑0 sum that works for dense and sparse matrices (returns 1‑D)."""
    if issparse(x):
        return np.asarray(x.sum(axis=0)).ravel()
    return x.sum(axis=0)

# 2 × k Chi‑square (statistic only) -------------------------------------------
@njit(cache=True)
def _chi2_stat(a: np.ndarray, b: np.ndarray):
    n1, n2 = a.sum(), b.sum()
    tot = n1 + n2
    exp1 = (a + b) * (n1 / tot)
    exp2 = (a + b) * (n2 / tot)
    chi2_val = ((a - exp1) ** 2 / exp1).sum() + ((b - exp2) ** 2 / exp2).sum()
    dof = a.size - 1
    return chi2_val, dof

# ---------------------------------------------------------------------------
# Main class
# ---------------------------------------------------------------------------

class SwitchSearch(ad.AnnData):
    """High‑performance isoform‑switch search (Chi²)."""

    # -------------------------------------------------------------------
    # Construction
    # -------------------------------------------------------------------

    def __init__(
        self,
        anndata_obj: ad.AnnData,
        n_jobs: int = -1,
        compute_metrics: bool = False,
        fast_mode: bool = True,
        group_column: str = "cell_type",
        condition_column: Optional[str] = None,
    ):
        super().__init__(anndata_obj.copy())
        self.n_jobs = os.cpu_count() if n_jobs in (-1, 0) else n_jobs
        self.fast_mode = fast_mode
        self.group_column = group_column
        self.condition_column = condition_column

        # guarantee transcriptId exists
        if "transcriptId" not in self.var.columns:
            self.var["transcriptId"] = self.var.index

        self.transcript_metrics: Optional[pd.DataFrame] = None
        self.gene_metrics_table: Optional[pd.DataFrame] = None
        if compute_metrics and not fast_mode:
            self._build_metrics(group_column)

    # -------------------------------------------------------------------
    # Metric helpers
    # -------------------------------------------------------------------

    def _build_metrics(self, group_column: str):
        """Compute transcript‑ and gene‑level metrics in advance."""
        try:
            from allos.preprocessing import get_sot_gene_matrix

            self.transcript_metrics = build_isoform_metrics_table(
                self,
                group_column=group_column,
                comparisons=None,
                epsilon=1e-6,
                n_jobs=self.n_jobs,
            )

            adata_gene = get_sot_gene_matrix(self)
            if "geneId" not in adata_gene.var.columns:
                adata_gene.var["geneId"] = adata_gene.var.index
            self.gene_metrics_table = build_gene_metrics_table(
                adata_gene,
                group_column=group_column,
                comparisons=None,
                epsilon=1e-6,
                n_jobs=self.n_jobs,
            )
        except Exception as e:
            warnings.warn(f"Metric pre‑compute failed: {e}")

    # -------------------------------------------------------------------
    # Internal helpers
    # -------------------------------------------------------------------

    def _filter_gene_idx(self, g1: str, g2: str, min_reads: int, cg: str) -> np.ndarray:
        """Return array indices of isoforms passing min‑read filter."""
        m1, m2 = (self.obs[cg] == g1).values, (self.obs[cg] == g2).values
        mask = (safe_sum(self.X[m1]) > min_reads) & (safe_sum(self.X[m2]) > min_reads)
        return np.flatnonzero(mask)

    def _merge_and_prune(
        self,
        base: pd.DataFrame,
        metrics: pd.DataFrame,
        drop_missing: bool,
    ) -> pd.DataFrame:
        """Merge `metrics` into `base` and optionally drop rows lacking metrics."""
        merged = base.merge(
            metrics,
            on=["gene_id", "group_1", "group_2"],
            how="left",
            suffixes=("", "_alt"),
        )

        # consolidate primary / alt columns
        meta_cols = {"gene_id", "group_1", "group_2"}
        metric_cols = [c for c in metrics.columns if c not in meta_cols]
        for col in metric_cols:
            alt = f"{col}_alt"
            if alt in merged.columns:
                if col in merged.columns:
                    merged[col] = merged[col].fillna(merged[alt])
                else:
                    merged[col] = merged[alt]
                merged.drop(columns=alt, inplace=True)

        if drop_missing and metric_cols:
            keep_cols = [c for c in metric_cols if c in merged.columns]
            merged = merged.dropna(subset=keep_cols, how="all")
        return merged

    # -------------------------------------------------------------------
    # Public API
    # -------------------------------------------------------------------

    def find_switching_isoforms_chi2(
        self,
        cell_group_column: str = "cell_type",
        min_reads: int = 30,
        min_fdr: float = 0.05,
        return_transcript_metrics: bool = False,
        drop_unmatched_metrics: bool = True,
        n_jobs: Optional[int] = None,
    ) -> pd.DataFrame:
        """Run Chi² screen and return genes with metrics (if available)."""

        n_jobs = n_jobs or self.n_jobs
        cg = cell_group_column

        # 1 — valid groups & pre‑aggregate isoform counts (boolean mask to ndarray!)
        cell_counts = self.obs[cg].value_counts()
        valid_groups = cell_counts[cell_counts >= min_reads].index.tolist()
        comparisons = list(itertools.combinations(valid_groups, 2))
        iso_counts: Dict[str, np.ndarray] = {
            g: safe_sum(self.X[(self.obs[cg] == g).values]) for g in valid_groups
        }

        # 2 — worker for each pair
        def _proc(g1: str, g2: str):
            idx = self._filter_gene_idx(g1, g2, min_reads, cg)
            if idx.size == 0:
                return []
            gene_ids = self.var["geneId"].values[idx]
            out: list[dict] = []
            for gene in np.unique(gene_ids):
                iso_idx = idx[gene_ids == gene]
                if iso_idx.size < 2:
                    continue
                a = iso_counts[g1][iso_idx].astype(np.float64)
                b = iso_counts[g2][iso_idx].astype(np.float64)
                stat, dof = _chi2_stat(a, b)
                out.append({
                    "gene_id": gene,
                    "group_1": g1,
                    "group_2": g2,
                    "chi2_stat": stat,
                    "p_value": chi2.sf(stat, dof),
                    "dof": dof,
                })
            return out

        results = Parallel(n_jobs=n_jobs, backend="threading", prefer="threads")(
            delayed(_proc)(g1, g2) for g1, g2 in comparisons
        )
        res_df = pd.DataFrame([row for sub in results for row in sub])
        if res_df.empty:
            return res_df

        # 3 — FDR
        from statsmodels.stats.multitest import multipletests
        res_df["adj_pval"] = multipletests(res_df["p_value"], method="fdr_bh")[1]
        res_df = res_df[res_df["adj_pval"] <= min_fdr].copy()
        if res_df.empty:
            return res_df

        # 4 — ensure transcript metrics for sig genes (fast‑mode)
        if self.fast_mode and self.transcript_metrics is None:
            sig_genes = res_df["gene_id"].unique()
            adata_sub = self[:, self.var["geneId"].isin(sig_genes)]
            try:
                self.transcript_metrics = build_isoform_metrics_table(
                    adata_sub,
                    group_column=cg,
                    comparisons=None,
                    epsilon=1e-6,
                    n_jobs=n_jobs,
                )
            except Exception as e:
                warnings.warn(f"Fast‑mode transcript metrics failed: {e}")

        # 5 — merge metrics
        if return_transcript_metrics and self.transcript_metrics is not None:
            tm = self.transcript_metrics
            filt = (
                tm["gene_id"].isin(res_df["gene_id"]) &
                ((tm["percent_expr_group1"] >= 0.2) | (tm["percent_expr_group2"] >= 0.2)) &
                (tm["total_count"] >= min_reads) &
                (tm["delta_psi"].abs() > 0.1)
            )
            base = res_df.copy()
            merged = self._merge_and_prune(base, tm.loc[filt], drop_unmatched_metrics)
            swapped = tm.loc[filt].rename(columns={"group_1": "group_2", "group_2": "group_1"})
            return self._merge_and_prune(merged, swapped, drop_unmatched_metrics)

        if self.gene_metrics_table is not None:
            gmt = self.gene_metrics_table
            base = res_df.copy()
            merged = self._merge_and_prune(base, gmt, drop_unmatched_metrics)
            gmt_sw = gmt.rename(columns={"group_1": "group_2", "group_2": "group_1"})
            return self._merge_and_prune(merged, gmt_sw, drop_unmatched_metrics)

        return res_df


