import pandas as pd
from scipy.stats import spearmanr

def compute_as_similarity(
    adata: ad.AnnData,
    group_column: str,
    transcripts: list[str],
    epsilon: float = 1e-6,
) -> pd.DataFrame:
    """
    Compute an AS‐similarity matrix (Spearman ρ) between all levels of `group_column`,
    using the PSI values of `transcripts`.

    Parameters
    ----------
    adata
        An AnnData containing your transcript‐by‐cell counts.
    group_column
        Column in adata.obs defining your cell groups (e.g. “cell_type”).
    transcripts
        List of var_names (transcript IDs) to include in the calculation.
    epsilon
        Small pseudocount to avoid division by zero when computing PSI.

    Returns
    -------
    corr_df : DataFrame
        A square DataFrame indexed and columned by the unique values of `group_column`,
        where corr_df.loc[g1, g2] is the Spearman ρ between the average‐PSI vectors
        of group g1 and group g2.
    """
    # 1) get cell‐level PSI matrix: cells × transcripts
    psi_mat = compute_cell_level_psi(adata, transcripts, epsilon)  
    psi_df = pd.DataFrame(psi_mat, 
                          index=adata.obs_names, 
                          columns=transcripts)

    # 2) tack on the group label, then average PSI per group
    psi_df[group_column] = adata.obs[group_column].values
    group_avg = psi_df.groupby(group_column).mean()

    # 3) compute pairwise Spearman correlations between group‐average PSI vectors
    groups = group_avg.index
    corr = pd.DataFrame(index=groups, columns=groups, dtype=float)
    for g1 in groups:
        for g2 in groups:
            ρ, _ = spearmanr(group_avg.loc[g1], group_avg.loc[g2])
            corr.loc[g1, g2] = ρ

    return corr


# %% ../nbs/005_switch_search.ipynb 16
def get_top_n_isoforms(adata, gene_id, top_n=5, strip=False):
    """
    Get the top_n transcript IDs for a given gene based on overall average expression.

    Parameters:
    - adata: AnnData object containing transcript-level data.
    - gene_id: The gene ID to search for corresponding isoforms.
    - top_n: The number of top isoforms to return based on overall average expression.
    - strip: Boolean indicating whether to strip the dot and everything after from the ID.

    Returns:
    - A list of top_n transcript IDs.
    """
    # Identify isoforms for the given gene ID
    isoforms = adata.var[adata.var['geneId'] == gene_id].index
    if len(isoforms) == 0:
        print(f"No isoforms found for gene ID: {gene_id}")
        return []

    # Calculate the overall average expression for each isoform
    overall_expr = adata.to_df()[isoforms].mean()

    # Get the top_n isoforms by average expression
    top_isoforms = overall_expr.sort_values(ascending=False).head(top_n).index.tolist()

    # Strip the dot and everything after from the ID if strip is True
    if strip:
        top_isoforms = [isoform.split('.')[0] for isoform in top_isoforms]

    return top_isoforms

